___CSS_LOADER_EXPORT___.push([module.id, "\nbody > .expandable-image.expanded {\n  width: 100% !important;\n}\n.expandable-image{\n  width: 100px;\n}\n", "",{"version":3,"sources":["webpack://./resources/assets/js/views/inventory/Index.vue"],"names":[],"mappings":";AA0NA;EACA,sBAAA;AACA;AACA;EACA,YAAA;AACA","sourcesContent":["<template>\n  <div class=\"items main-content\">\n    <div class=\"page-header\">\n      <div class=\"d-flex flex-row\">\n        <div>\n          <h3 class=\"page-title\">{{ $tc('inventory.inventory', 2) }}</h3>\n        </div>\n      </div>\n      <ol class=\"breadcrumb\">\n        <li class=\"breadcrumb-item\">\n          <router-link\n            slot=\"item-title\"\n            to=\"/\">\n            {{ $t('general.home') }}\n          </router-link>\n        </li>\n        <li class=\"breadcrumb-item\">\n          <router-link\n            slot=\"item-title\"\n            to=\"#\">\n            {{ $tc('inventory.inventory', 2) }}\n          </router-link>\n        </li>\n      </ol>\n      <div class=\"page-actions row\">\n        <div class=\"col-xs-2 mr-4\">\n          <base-button\n            v-show=\"totalInventories || filtersApplied\"\n            :outline=\"true\"\n            :icon=\"filterIcon\"\n            color=\"theme\"\n            size=\"large\"\n            right-icon\n            @click=\"toggleFilter\"\n          >\n            {{ $t('general.filter') }}\n          </base-button>\n        </div>\n        <router-link slot=\"item-title\" class=\"col-xs-2\" to=\"inventory/create\">\n          <base-button\n            color=\"theme\"\n            icon=\"plus\"\n            size=\"large\"\n          >\n            {{ $t('inventory.new_inventory') }}\n          </base-button>\n        </router-link>\n      </div>\n    </div>\n\n    <transition name=\"fade\">\n      <div v-show=\"showFilters\" class=\"filter-section\">\n        <div class=\"row\">\n          <div class=\"col-sm-3\">\n            <label class=\"form-label\"> {{ $tc('inventory.name') }} </label>\n            <base-input\n              v-model.trim=\"filters.name\"\n              type=\"text\"\n              name=\"name\"\n              autocomplete=\"off\"\n            />\n          </div>\n          <label class=\"clear-filter\" @click=\"clearFilter\"> {{ $t('general.clear_all') }}</label>\n        </div>\n      </div>\n    </transition>\n\n    <div v-cloak v-show=\"showEmptyScreen\" class=\"col-xs-1 no-data-info\" align=\"center\">\n      <satellite-icon class=\"mt-5 mb-4\"/>\n      <div class=\"row\" align=\"center\">\n        <label class=\"col title\">{{ $t('inventory.no_inventory') }}</label>\n      </div>\n      <div class=\"row\">\n        <label class=\"description col mt-1\" align=\"center\">{{ $t('inventory.list_of_inventory') }}</label>\n      </div>\n      <div class=\"btn-container\">\n        <base-button\n          :outline=\"true\"\n          color=\"theme\"\n          class=\"mt-3\"\n          size=\"large\"\n          @click=\"$router.push('inventory/create')\"\n        >\n          {{ $t('inventory.add_new_inventory') }}\n        </base-button>\n      </div>\n    </div>\n\n    <div v-show=\"!showEmptyScreen\" class=\"table-container\">\n      <div class=\"table-actions mt-5\">\n        <p class=\"table-stats\">{{ $t('general.showing') }}: <b>{{ inventory.length }}</b> {{ $t('general.of') }} <b>{{ totalInventories }}</b></p>\n        <transition name=\"fade\">\n          <v-dropdown v-if=\"selectedInventory\" :show-arrow=\"false\">\n            <span slot=\"activator\" href=\"#\" class=\"table-actions-button dropdown-toggle\">\n              {{ $t('general.actions') }}\n            </span>\n            <v-dropdown-item>\n              <div class=\"dropdown-item\" @click=\"openIncreasePriceModal\">\n                <font-awesome-icon :icon=\"['fas', 'pencil-alt']\" class=\"dropdown-item-icon\" />\n                {{ $t('general.increase-price') }}\n              </div>\n            </v-dropdown-item>\n            <v-dropdown-item>\n              <div class=\"dropdown-item\" @click=\"removeMultipleInventory\">\n                <font-awesome-icon :icon=\"['fas', 'trash']\" class=\"dropdown-item-icon\" />\n                {{ $t('general.delete') }}\n              </div>\n            </v-dropdown-item>\n          </v-dropdown>\n        </transition>\n      </div>\n\n      <div class=\"custom-control custom-checkbox\">\n        <input\n          id=\"select-all-inventory\"\n          v-model=\"selectAllFieldStatus\"\n          type=\"checkbox\"\n          class=\"custom-control-input\"\n          @change=\"selectAllInventory\"\n        >\n        <label v-show=\"!isRequestOngoing\" for=\"select-all-inventory\" class=\"custom-control-label selectall\">\n          <span class=\"select-all-label\">{{ $t('general.select_all') }} </span>\n        </label>\n      </div>\n\n      <table-component\n        ref=\"table\"\n        :data=\"fetchData\"\n        :show-filter=\"false\"\n        table-class=\"table\"\n      >\n\n        <table-column\n          :sortable=\"false\"\n          :filterable=\"false\"\n          cell-class=\"no-click\"\n        >\n          <template slot-scope=\"row\">\n            <div class=\"custom-control custom-checkbox\">\n              <input\n                :id=\"row.id\"\n                v-model=\"selectField\"\n                :value=\"row.id\"\n                type=\"checkbox\"\n                class=\"custom-control-input\"\n              >\n              <label :for=\"row.id\" class=\"custom-control-label\"/>\n            </div>\n          </template>\n        </table-column>\n        <table-column\n          :label=\"$t('inventory.name')\"\n          show=\"name\"\n        >\n          <template slot-scope=\"row\">\n            <router-link :to=\"{path: `inventory/${row.id}/edit`}\">\n               {{ row.name }}\n              </router-link>\n          </template>\n        </table-column>\n        <table-column\n          :label=\"$t('inventory.unit')\"\n          show=\"unit\"\n        >\n          <template slot-scope=\"row\">\n            {{ row.unit }}\n          </template>\n        </table-column>\n        <table-column\n          :label=\"$t('inventory.avg_price')\"\n          show=\"price\"\n        >\n          <template slot-scope=\"row\">\n            ₹ {{ numberWithCommas(row.price) }}\n          </template>\n        </table-column>\n        <table-column\n          :label=\"$t('inventory.quantity')\"\n          show=\"quantity\"\n        />\n         <!-- <table-column\n          :label=\"$t('inventory.worker_name')\"\n          show=\"worker_name\"\n        /> -->\n        <table-column\n          :key=\"Math.random()\"\n          :sortable=\"false\"\n          :filterable=\"false\"\n          cell-class=\"action-dropdown\"\n        >\n        <template slot-scope=\"row\">\n          <span> {{ $t('inventory.action') }} </span>\n          <v-dropdown>\n            <span slot=\"activator\" href=\"#\">\n              <dot-icon />\n            </span>\n            <v-dropdown-item>\n\n              <router-link :to=\"{path: `inventory/${row.id}/edit`}\" class=\"dropdown-item\">\n                <font-awesome-icon :icon=\"['fas', 'pencil-alt']\" class=\"dropdown-item-icon\" />\n                {{ $t('general.edit') }}\n              </router-link>\n\n            </v-dropdown-item>\n            <v-dropdown-item>\n              <div class=\"dropdown-item\" @click=\"removeInventory(row.id)\">\n                <font-awesome-icon :icon=\"['fas', 'trash']\" class=\"dropdown-item-icon\" />\n                {{ $t('general.delete') }}\n              </div>\n            </v-dropdown-item>\n          </v-dropdown>\n        </template>\n      </table-column>\n      </table-component>\n    </div>\n  </div>\n</template>\n<style>\nbody > .expandable-image.expanded {\n  width: 100% !important;\n}\n.expandable-image{\n  width: 100px;\n}\n</style>\n<script>\nimport { mapActions, mapGetters } from 'vuex'\nimport DotIcon from '../../components/icon/DotIcon'\nimport SatelliteIcon from '../../components/icon/SatelliteIcon'\nimport BaseButton from '../../../js/components/base/BaseButton'\nimport GlobalMixin from '../../helpers/mixins.js';\nexport default {\n  components: {\n    DotIcon,\n    SatelliteIcon,\n    BaseButton,\n  },\n  mixins:[GlobalMixin],\n  data () {\n    return {\n      id: null,\n      showFilters: false,\n      sortedBy: 'created_at',\n      isRequestOngoing: true,\n      filtersApplied: false,\n      filters: {\n        name: '',\n        worker_name: '',\n        unit: '',\n        price: '',\n        quantity: ''\n      },\n      index: null\n    }\n  },\n  computed: {\n    ...mapGetters('inventory', [\n      'inventory',\n      'inventories',\n      'selectedInventory',\n      'totalInventories',\n      'selectAllField'\n    ]),\n    showEmptyScreen () {\n      return !this.totalInventories && !this.isRequestOngoing && !this.filtersApplied\n    },\n    filterIcon () {\n      return (this.showFilters) ? 'times' : 'filter'\n    },\n    selectField: {\n      get: function () {\n        return this.selectedInventory\n      },\n      set: function (val) {\n        this.selectInventory(val)\n      }\n    },\n    selectAllFieldStatus: {\n      get: function () {\n        return this.selectAllField\n      },\n      set: function (val) {\n        this.setSelectAllState(val)\n      }\n    }\n  },\n  watch: {\n    filters: {\n      handler: 'setFilters',\n      deep: true\n    }\n  },\n  destroyed () {\n    if (this.selectAllField) {\n      this.selectAllInventory()\n    }\n  },\n  methods: {\n    ...mapActions('modal', [\n      'openModal'\n    ]),\n    ...mapActions('inventory', [\n      'fetchAllInventory',\n      'selectAllInventory',\n      'selectInventory',\n      'deleteInventory',\n      'deleteMultipleInventory',\n      'setSelectAllState'\n    ]),\n    refreshTable () {\n      this.$refs.table.refresh()\n    },\n    async fetchData ({ page, filter, sort }) {\n      let data = {\n        name: this.filters.name !== null ? this.filters.name : '',\n        price: this.filters.price !== null ? this.filters.price : '',\n        quantity: this.filters.quantity !== null ? this.filters.quantity : '',\n        unit: this.filters.unit !== null ? this.filters.unit : '',\n        worker_name: this.filters.worker_name !== null ? this.filters.worker_name : '',\n        orderByField: sort.fieldName || 'created_at',\n        orderBy: sort.order || 'desc',\n        page\n      }\n\n      this.isRequestOngoing = true\n      let response = await this.fetchAllInventory(data)\n      this.isRequestOngoing = false\n      return {\n        data: this.inventories, //from state, see mutation\n        pagination: {\n          totalPages: response.data.inventories.last_page,\n          currentPage: page\n        }\n      }\n    },\n    setFilters () {\n      if (this.timer) {\n          clearTimeout(this.timer);\n          this.timer = null;\n      }\n      this.timer = setTimeout(() => {\n\t\t\t\tthis.filtersApplied = true\n        this.refreshTable()\n\t\t\t}, 1000);\n    },\n    clearFilter () {\n      this.filters = {\n        name: '',\n        unit: '',\n        worker_name: '',\n        price: '',\n        quantity: ''\n      }\n\n      this.$nextTick(() => {\n        this.filtersApplied = false\n      })\n    },\n    toggleFilter () {\n      if (this.showFilters && this.filtersApplied) {\n        this.clearFilter()\n        this.refreshTable()\n      }\n\n      this.showFilters = !this.showFilters\n    },\n    async removeInventory (id) {\n      this.id = id\n      swal({\n        title: this.$t('general.are_you_sure'),\n        text: this.$tc('inventory.confirm_delete'),\n        icon: '/assets/icon/trash-solid.svg',\n        buttons: true,\n        dangerMode: true\n      }).then(async (willDelete) => {\n        if (willDelete) {\n          let resp = await this.deleteInventory(this.id)\n          if (resp.data.success) {\n            window.toastr['success'](this.$tc('inventory.deleted_message', 1))\n            this.$refs.table.refresh()\n          }\n        }\n      }).catch(err => {\n        window.toastr['error'](err.response.data.message)\n      })\n    },\n    openIncreasePriceModal () {\n      //this.$emit('onIncreasePrice')\n      this.openModal({\n        'title': 'Increase Inventory Price',\n        'componentName': 'IncreasePriceModal',\n        'data': this.selectedInventory\n      })\n    },\n    async removeMultipleInventory () {\n      swal({\n        title: this.$t('general.are_you_sure'),\n        text: this.$tc('inventory.confirm_delete', 2),\n        icon: '/assets/icon/trash-solid.svg',\n        buttons: true,\n        dangerMode: true\n      }).then(async (willDelete) => {\n        if (willDelete) {\n          let resp = await this.deleteMultipleInventory()\n          if (resp.data) {\n            window.toastr['success'](this.$tc('inventory.deleted_message', 2))\n            this.$refs.table.refresh()\n          }\n        }\n      }).catch((err) => {\n        console.log(err)\n        window.toastr['error'](err.response.data.message)\n      })\n    },\n    setIndex(index) {\n      this.index = index\n    }\n  }\n}\n</script>\n"],"sourceRoot":""}]);
